ACTION_VERSION = "BHSM-AE-3.2.0-RESET-GENERATOR-ADJUDICATION"
CLASSIFICATION = "GFHS_AE4_RESET_CANONICAL_GENERATOR_ADJUDICATION"
STATUS = "RESET_MAP_INSUFFICIENTLY_DEFINED_ON_NONZERO_GAUGE_CONNECTION_TRACE"
